function loadTipsContent(){const n=document.getElementById("tips-content");if(n){if(typeof DOMPurify=="undefined"||typeof DOMPurify.sanitize!="function"){n.textContent=t("Tips temporarily unavailable. Please refresh the page.");return}fetch("/tips/content").then(e=>{if(!e.ok)throw new Error("Failed to load tips content: Network response was not OK");return e.text()}).then(e=>{n.innerHTML=DOMPurify.sanitize(e)}).catch(e=>{n.textContent=t("Tips temporarily unavailable. Please refresh the page.")})}}window.loadTipsContent=loadTipsContent;
